            cpu->s = (uint16_t)(cpu->s - 1u);
            cpu->pbr = 0xCDu;
            cpu->pc = 0x33F5u;
            if (nh_scpu_expect_next(cpu, 0x06699FA8u) != NH_SCPU_EXECUTED)
                return NH_SCPU_STOPPED;
            return nh_scpu_finish(cpu, bus, 4u);
